// Package gen emits Go source for a lowered Alder program (internal/ir). Every Alder module
// becomes one file of package app; names follow GoName, types follow GoType, and the code calls
// the runtime in alder/rt, alder/rt/html and alder/rt/std.
package gen

import (
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"maps"
	"slices"
	"strconv"
	"strings"

	"alder/internal/ir"
	"alder/internal/types"
)

// Options configure Emit.
type Options struct {
	// Version is the compiler's version (internal/version.String), recorded in app__alder.go's
	// header: "// Code generated by alder <Version>; DO NOT EDIT.". Empty leaves it out ("//
	// Code generated by alder; DO NOT EDIT."), as the golden tests do, so a golden does not
	// change with the binary that wrote it.
	Version string
	Dev     bool
	// Migrations: the app has migrations (migrations/*.sql, copied next to the generated files
	// by buildkit.CopyMigrations), which app__alder.go embeds as Migrations; without, Migrations
	// is empty and Serve uses db.Ensure.
	Migrations bool
	// Tests makes a test build (the scratch builds of alder test, eval and repl): the app's
	// `test` declarations are emitted (one function each, test__M__n) with Tests and
	// TestSession in app__alder.go, and each `fake` is emitted — its tables' records and
	// descriptors and its entries in its module's file, a struct implementing its capability
	// (fake__M__C), FakeTables and Fakes in app__alder.go — and Test.fake installs the fake in
	// the running test's Env.Caps; the browser steps' helpers are emitted too: each form's
	// encoder (encode__M__F, routes__alder.go), the selector literals of the queries
	// (selector__N) and, for an app without an App module, an empty Routes and Web (the test
	// main passes both to rtesting.Main). Without it (alder build: every production build) none
	// of that is emitted, so the production module carries no test code and does not import
	// alder/rt/testing; a test node (Test.run, Test.trace, Test.fake, a browser step, a test's
	// `==`) reaching the emitter there is a bug in gen, reported as Emit's error.
	Tests bool
	// Unwired, in a test build only, are the capabilities (keys "M.C", as in Capabilities)
	// whose adapters are missing (buildkit.CheckTestAdapters): the caps package leaves their
	// fields nil and does not import a package that has none of the others, so a call of one
	// fails "not wired in tests". Emit refuses it in a production build, which wires every one.
	Unwired map[string]bool
	// Mutate, with Tests (alder test --mutate), compiles every mutant mutate.Collect finds
	// into the test build as a switch on the package variable Mutant (mutation.go): each
	// mutated node is emitted as `switch Mutant { case id: <its replacement> }` before the
	// original, a page's `requires` serves a placeholder under its id, and app__alder.go
	// holds Mutant, Mutants (the table rtesting runs, with each schema mutant's tables) and
	// the refused counts. Every constant becomes a thunk, so a mutant reaches it at run time.
	// Without it nothing of this is emitted.
	Mutate bool
	// Thunks names constants ("Module.name") to emit as thunks, functions of no parameters
	// called at each use, as a generic one is: a scratch file's watches, so that a panic in one
	// happens at its call, where the caller's main recovers it, not at package init. A named
	// function or unknown name is ignored.
	Thunks map[string]bool
}

// Emit returns the generated files: one "<Module>_alder.go" per module ('.' → "__"),
// "app__alder.go" (Tables, Migrations, Capabilities, Caps and, with an App module, Options, Serve and Web),
// "routes__alder.go" with an App module (the routes: routes.go), "go.mod" and, when the app has
// capabilities, CapsFile ("caps/caps__alder.go", package caps: CapsPackage), which imports the
// adapter packages under adapters/ (copied next to it by buildkit.CopyAdapters).
// Its error is for a bug in gen: output go/format cannot parse, or a program gen cannot emit
// (such as a stdlib function with no Go implementation), or two modules or declarations that
// would get the same file or Go name; and for two capabilities whose adapters would be the same
// constructor (AdapterCollision), an internal naming error naming both.
func Emit(p *ir.Program, opts Options) (files map[string][]byte, err error) {
	defer func() {
		if r := recover(); r != nil {
			files, err = nil, fmt.Errorf("%v", r)
		}
	}()
	g := newGen(p, opts.Thunks)
	g.indexFakes(p, opts.Tests)
	if opts.Mutate {
		if !opts.Tests {
			return nil, fmt.Errorf("gen: Mutate without Tests")
		}
		g.indexMutants(p)
	}
	files = map[string][]byte{"go.mod": []byte(goMod)}
	declared := map[string]string{} // Go name → module declaring it
	for _, m := range p.Modules {
		src, err := g.module(m)
		if err != nil {
			return nil, err
		}
		name := fileName(m.Name)
		if _, dup := files[name]; dup {
			return nil, fmt.Errorf("gen: two modules are emitted to %s", name)
		}
		files[name] = src
		// Defense in depth: the naming scheme is injective (names.go), so this never fires.
		names, err := topLevelNames(src)
		if err != nil {
			return nil, fmt.Errorf("gen: module %s: %v", m.Name, err)
		}
		for _, n := range names {
			if prev, dup := declared[n]; dup {
				return nil, fmt.Errorf("gen: %s is declared twice (by %s and by module %s)", n, prev, m.Name)
			}
			declared[n] = "module " + m.Name
		}
	}
	if src := g.fuzzSource(); src != "" {
		out, err := sourceFile(src)
		if err != nil {
			return nil, fmt.Errorf("gen: %s: %v", fuzzFile, err)
		}
		if _, dup := files[fuzzFile]; dup {
			return nil, fmt.Errorf("gen: a module is emitted to %s", fuzzFile)
		}
		files[fuzzFile] = out
	}
	app, err := format.Source([]byte(g.appSource(p, opts.Migrations, opts.Version)))
	if err != nil {
		return nil, fmt.Errorf("gen: %s: %v", appFile, err)
	}
	if _, dup := files[appFile]; dup {
		return nil, fmt.Errorf("gen: a module is emitted to %s", appFile)
	}
	files[appFile] = app
	if p.Session != nil {
		src := g.routesSource(p)
		routes, err := format.Source([]byte(src))
		if err != nil {
			return nil, fmt.Errorf("gen: %s: %v\n%s", routesFile, err, src)
		}
		if routes, err = format.Source(routes); err != nil { // twice, as a module's file (a function literal's struct parameter)
			return nil, fmt.Errorf("gen: %s: %v", routesFile, err)
		}
		if _, dup := files[routesFile]; dup {
			return nil, fmt.Errorf("gen: a module is emitted to %s", routesFile)
		}
		files[routesFile] = routes
	}
	for _, f := range []string{appFile, routesFile, fuzzFile} { // defense in depth, as above
		if files[f] == nil {
			continue
		}
		names, err := topLevelNames(files[f])
		if err != nil {
			return nil, fmt.Errorf("gen: %s: %v", f, err)
		}
		for _, n := range names {
			if prev, dup := declared[n]; dup {
				return nil, fmt.Errorf("gen: %s is declared twice (by %s and by %s)", n, prev, f)
			}
			declared[n] = f
		}
	}
	if len(p.Caps) > 0 {
		if err := AdapterCollisionError(p.Caps); err != nil {
			return nil, fmt.Errorf("gen: %v", err)
		}
		if len(opts.Unwired) > 0 && !opts.Tests {
			return nil, fmt.Errorf("gen: unwired capabilities in a production build")
		}
		files[CapsFile] = CapsPackage(p, opts.Unwired)
	}
	return files, nil
}

// topLevelNames lists the package-level names a generated file declares, with repeats.
func topLevelNames(src []byte) ([]string, error) {
	f, err := parser.ParseFile(token.NewFileSet(), "", src, parser.SkipObjectResolution)
	if err != nil {
		return nil, err
	}
	var out []string
	for _, d := range f.Decls {
		switch d := d.(type) {
		case *ast.FuncDecl:
			if d.Recv == nil {
				out = append(out, d.Name.Name)
			}
		case *ast.GenDecl:
			for _, sp := range d.Specs {
				switch sp := sp.(type) {
				case *ast.TypeSpec:
					out = append(out, sp.Name.Name)
				case *ast.ValueSpec:
					for _, n := range sp.Names {
						out = append(out, n.Name)
					}
				}
			}
		}
	}
	return out, nil
}

// goMod is the generated module's go.mod: the runtime, module alder, is the directory rt/ next
// to it (buildkit.WriteRuntime writes it there from the copy embedded in the compiler), so the
// path is relative and the build directory can be moved; nothing points into a checkout.
const goMod = "module app\n\ngo 1.27\n\nrequire alder v0.0.0\n\nreplace alder => ./rt\n"

// gen holds what emission needs across modules.
type gen struct {
	pages   map[string]*ir.Page  // by module
	session *ir.RecordType       // App's Session
	values  map[string]*ir.Value // "Module.name" → value or component
	thunks  map[*ir.Value]bool   // constants emitted as functions (see newGen)
	tparams map[*ir.Value][]string
	boxed   boxedSet // record fields held by pointer (types.go)
	// payloads are the nominal record payloads of constructors, by "Module.Union.Ctor"
	payloads map[string]*ir.RecordType
	tables   map[string][]*ir.Table      // by module, in declaration order
	caps     map[string][]*ir.Capability // by module, in declaration order
	brands   map[string][]*ir.Brand      // by module, in declaration order
	enums    map[string]bool             // unions stored in a table column (storedEnums)
	// tests: a test build (Options.Tests); fakes are the program's fakes by module
	tests bool
	fakes map[string][]*ir.Fake
	// selectors are the selector literals of the tests' queries, by text, with their package
	// variables (selector), in order of first use (selectorOrder)
	selectors     map[string]string
	selectorOrder []string
	// mutation is the mutate build's state (Options.Mutate; nil otherwise): mutation.go
	mutation *mutation
	// siloOf is the `silo` key of each siloed table, by "Module.Name" (M15)
	siloOf map[string]string
	prog   *ir.Program
	// fuzzes are the derived generators and printers the emitted code uses (fuzz.go)
	fuzzes *fuzzSet
}

// indexFakes records p's fakes for module and app emission. In a test build the unions their
// tables store get an enumDecl too.
func (g *gen) indexFakes(p *ir.Program, tests bool) {
	g.tests, g.fakes = tests, map[string][]*ir.Fake{}
	for _, fk := range p.Fakes {
		g.fakes[fk.Module] = append(g.fakes[fk.Module], fk)
		if tests {
			maps.Copy(g.enums, storedEnums(&ir.Program{Tables: fk.Tables}))
		}
	}
}

// newGen indexes the program's values. A constant (a value with no parameters and a non-function
// type) is a Go package variable, except that it is a function called at each use (a thunk) when
// it is generic (Go has no generic variables) or when its initializer refers back to itself
// through other values (Go rejects initialization cycles), or when thunks names it
// (Options.Thunks).
func newGen(p *ir.Program, thunks map[string]bool) *gen {
	g := &gen{values: map[string]*ir.Value{}, thunks: map[*ir.Value]bool{}, tparams: map[*ir.Value][]string{},
		pages: map[string]*ir.Page{}, session: p.Session, boxed: boxedFields(p), payloads: map[string]*ir.RecordType{},
		tables: map[string][]*ir.Table{}, caps: map[string][]*ir.Capability{}, brands: map[string][]*ir.Brand{}, enums: storedEnums(p),
		selectors: map[string]string{}, siloOf: map[string]string{}, prog: p}
	for k, ts := range p.Silos {
		for _, tb := range ts {
			g.siloOf[tb.Module+"."+tb.Name] = k
		}
	}
	for _, b := range p.Brands {
		g.brands[b.Module] = append(g.brands[b.Module], b)
	}
	for _, tb := range p.Tables {
		g.tables[tb.Module] = append(g.tables[tb.Module], tb)
	}
	for _, c := range p.Caps {
		g.caps[c.Module] = append(g.caps[c.Module], c)
	}
	for _, m := range p.Modules {
		for _, d := range m.Types {
			if d.Union == nil {
				continue
			}
			for _, c := range d.Union.Ctors {
				if c.Payload != nil && c.Payload.Name != "" {
					g.payloads[d.Union.Module+"."+d.Union.Name+"."+c.Name] = c.Payload
				}
			}
		}
	}
	for _, pg := range p.Pages {
		g.pages[pg.Module] = pg
	}
	var all []*ir.Value
	for _, m := range p.Modules {
		all = append(append(all, m.Values...), m.Components...)
	}
	refs := map[*ir.Value][]*ir.Value{}
	for _, v := range all {
		g.values[v.Module+"."+v.Name] = v
	}
	for _, v := range all {
		walk(v.Body, func(e ir.Expr) {
			switch x := e.(type) {
			case *ir.Var:
				if r := g.values[x.Module+"."+x.Name]; x.Kind == ir.VarGlobal && r != nil {
					refs[v] = append(refs[v], r)
				}
			case *ir.Comp:
				if x.Fn != nil {
					refs[v] = append(refs[v], x.Fn)
				}
			}
		})
	}
	for _, v := range all {
		if _, isFun := v.Type.(*types.Fun); isFun || len(v.Params) > 0 {
			continue
		}
		if len(g.params(v)) > 0 || reaches(refs, v) || thunks[v.Module+"."+v.Name] {
			g.thunks[v] = true
		}
	}
	return g
}

// reaches reports whether v refers to itself through the reference graph.
func reaches(refs map[*ir.Value][]*ir.Value, v *ir.Value) bool {
	seen := map[*ir.Value]bool{}
	stack := slices.Clone(refs[v])
	for len(stack) > 0 {
		r := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if r == v {
			return true
		}
		if !seen[r] {
			seen[r] = true
			stack = append(stack, refs[r]...)
		}
	}
	return false
}

// params are the Alder type parameters of v's Go declaration.
func (g *gen) params(v *ir.Value) []string {
	ps, ok := g.tparams[v]
	if !ok {
		ps = typeParams(v.Type)
		g.tparams[v] = ps
	}
	return ps
}

// instantiate is the explicit type argument list for a reference to generic value v at type t,
// "" when v is not generic. A type argument the checker left unsolved (`List.length empty` with
// `empty : List a`) is unconstrained, so any type will do: it is `any` (GoType of an inference
// variable), here and in every other type that mentions the same variable.
func (g *gen) instantiate(v *ir.Value, t types.Type) string {
	ps := g.params(v)
	if len(ps) == 0 {
		return ""
	}
	m := map[string]types.Type{}
	bindParams(v.Type, t, m)
	var args []string
	for _, p := range ps {
		if a := m[p]; a != nil {
			args = append(args, GoType(a))
		} else {
			args = append(args, "any")
		}
	}
	return "[" + strings.Join(args, ", ") + "]"
}

// bindParams matches declared type decl against its instance inst, recording what each type
// parameter stands for.
func bindParams(decl, inst types.Type, m map[string]types.Type) {
	switch d := decl.(type) {
	case *types.Param:
		if m[d.Name] == nil {
			m[d.Name] = inst
		}
	case *types.App:
		if i, ok := inst.(*types.App); ok && i.Con == d.Con && len(i.Args) == len(d.Args) {
			for k := range d.Args {
				bindParams(d.Args[k], i.Args[k], m)
			}
		}
	case *types.Union:
		if i, ok := inst.(*types.Union); ok && len(i.Args) == len(d.Args) {
			for k := range d.Args {
				bindParams(d.Args[k], i.Args[k], m)
			}
		}
	case *types.Record:
		if d.Name != "" && !d.Anonymous { // its parameters are in its arguments; it may be recursive
			if i, ok := inst.(*types.Record); ok && len(i.Args) == len(d.Args) {
				for k := range d.Args {
					bindParams(d.Args[k], i.Args[k], m)
				}
			}
			return
		}
		if i, ok := inst.(*types.Record); ok && len(i.Fields) == len(d.Fields) {
			for k := range d.Fields {
				bindParams(d.Fields[k].Type, i.Fields[k].Type, m)
			}
		}
	case *types.Fun:
		if i, ok := inst.(*types.Fun); ok && len(i.Params) == len(d.Params) {
			for k := range d.Params {
				bindParams(d.Params[k], i.Params[k], m)
			}
			bindParams(d.Result, i.Result, m)
		}
	}
}

// module emits one module's file.
func (g *gen) module(m *ir.Module) ([]byte, error) {
	var body strings.Builder
	for _, d := range m.Types {
		typeDecl(&body, d, g.boxed)
		if d.Union != nil && g.enums[d.Module+"."+d.Name] {
			enumDecl(&body, d.Union)
		}
	}
	for _, tb := range g.tables[m.Name] {
		g.tableDecl(&body, tb)
	}
	for _, c := range g.caps[m.Name] {
		capDecl(&body, c)
	}
	if g.tests {
		for _, fk := range g.fakes[m.Name] {
			for _, tb := range fk.Tables {
				body.WriteString(comment(fmt.Sprintf("%s is table %s of `fake %s` (test builds only: rtesting creates it after the app's tables, from FakeTables).",
					GoName(tb.Module, tb.Name), tb.Name, fk.Capability.Name)))
				typeDecl(&body, &ir.TypeDecl{Module: tb.Module, Name: tb.Name, Record: tb.Record}, g.boxed)
				g.tableDecl(&body, tb)
			}
			fakeDecl(&body, fk)
		}
	}
	for _, b := range g.brands[m.Name] {
		if b.Check != nil {
			g.checkDecl(&body, b)
		}
	}
	if pg := g.pages[m.Name]; pg != nil && len(pg.Requires) > 0 && pg.Session != g.session {
		widenFunc(&body, pg, g.session, g.boxed)
	}
	for _, v := range m.Values {
		g.value(&body, v)
	}
	for _, v := range m.Components {
		g.value(&body, v)
	}
	if g.tests {
		for _, fk := range g.fakes[m.Name] {
			for _, v := range fk.Entries {
				g.valueAs(&body, v, fakeEntry(fk.Module, fk.Capability.Name, v.Name))
			}
		}
	}
	if g.tests {
		for i, t := range m.Tests {
			g.test(&body, t, i+1)
		}
	}
	out, err := sourceFile(body.String())
	if err != nil {
		return nil, fmt.Errorf("gen: module %s: %v", m.Name, err)
	}
	return out, nil
}

// sourceFile is a generated file of package app with body's declarations: the header, the
// imports body uses, formatted.
func sourceFile(body string) ([]byte, error) {
	imports, err := importsOf(body)
	if err != nil {
		return nil, fmt.Errorf("%v\n%s", err, body)
	}
	src := "// Code generated by alder; DO NOT EDIT.\n\npackage app\n\n" + importBlock(imports) + body
	out, err := format.Source([]byte(src))
	if err != nil {
		return nil, fmt.Errorf("%v\n%s", err, src)
	}
	// Once more: go/printer lays a function literal out by its source lines, which the first pass
	// changes (a struct parameter type grows to several lines), so only the second output is one
	// gofmt leaves alone.
	return format.Source(out)
}

// packages are the imports generated code may need, by package name.
var packages = map[string]string{
	"rt": "alder/rt", "html": "alder/rt/html", "std": "alder/rt/std", "time": "time", "math": "math",
	"eff": "alder/rt/eff", "db": "alder/rt/db", "context": "context", "fmt": "fmt",
	"web": "alder/rt/web", "url": "net/url", "http": "net/http", "json": "encoding/json", "errors": "errors",
	"strings": "strings", "reflect": "reflect", "rtesting": "alder/rt/testing", "embed": "embed",
	"filepath": "path/filepath", "fuzz": "alder/rt/fuzz",
}

// importNames are the packages whose name is not their path's last element, by path: they are
// imported under that name.
var importNames = map[string]string{"alder/rt/testing": "rtesting"}

// importsOf lists the import paths body refers to. Locals never take a package's name (see
// local), so a selector on such a name is a package reference.
func importsOf(body string) ([]string, error) {
	f, err := parser.ParseFile(token.NewFileSet(), "", "package app\n"+body, parser.SkipObjectResolution)
	if err != nil {
		return nil, err
	}
	used := map[string]bool{}
	ast.Inspect(f, func(n ast.Node) bool {
		if sel, ok := n.(*ast.SelectorExpr); ok {
			if id, ok := sel.X.(*ast.Ident); ok && packages[id.Name] != "" {
				used[packages[id.Name]] = true
			}
		}
		return true
	})
	var out []string
	for p := range used {
		out = append(out, p)
	}
	slices.Sort(out) // format.Source would sort them anyway
	return out, nil
}

// value emits a top-level value or component: a function when its type is a function (with
// all the signature's parameters, also those its definition leaves to a function-valued body),
// else a package variable or, for a thunk, a function of no parameters.
func (g *gen) value(w *strings.Builder, v *ir.Value) {
	g.valueAs(w, v, GoName(v.Module, v.Name))
}

// valueAs is value with the Go name name (a fake's entry: fakeEntry).
func (g *gen) valueAs(w *strings.Builder, v *ir.Value, name string) {
	f := &fn{g: g}
	s := newScope()
	tps := typeParamDecl(g.params(v))
	ft, isFun := v.Type.(*types.Fun)
	if !isFun {
		if g.thunks[v] {
			var b strings.Builder
			f.ret(&b, v.Body, s)
			fmt.Fprintf(w, "func %s%s() %s {\n%s}\n\n", name, tps, GoType(v.Type), b.String())
			return
		}
		fmt.Fprintf(w, "var %s %s = %s\n\n", name, GoType(v.Type), f.code(v.Body, s))
		return
	}
	var params []string
	for _, p := range v.Params {
		params = append(params, s.declare(p.Name)+" "+GoType(p.Type))
	}
	body := v.Body
	rest := ft.Params[min(len(v.Params), len(ft.Params)):]
	// a function-valued body: its lambda's parameters become the function's own
	for len(rest) > 0 {
		l, ok := body.(*ir.Lambda)
		if !ok || len(l.Params) > len(rest) {
			break
		}
		for _, p := range l.Params {
			params = append(params, s.declare(p.Name)+" "+GoType(p.Type))
		}
		rest, body = rest[len(l.Params):], l.Body
	}
	if len(rest) > 0 { // otherwise apply the body to the remaining parameters
		var extra []ir.Expr
		for _, t := range rest {
			key, p := f.tempVar(s, "_a")
			params = append(params, p+" "+GoType(t))
			extra = append(extra, &ir.Var{Typed: ir.Typed{Ty: t}, Kind: ir.VarLocal, Name: key})
		}
		if pa, ok := body.(*ir.Partial); ok && pa.Missing == len(extra) {
			body = &ir.Call{Typed: ir.Typed{Ty: ft.Result}, Fn: pa.Fn, Args: append(slices.Clone(pa.Given), extra...)}
		} else {
			body = &ir.Call{Typed: ir.Typed{Ty: ft.Result}, Fn: body, Args: extra}
		}
	}
	var b strings.Builder
	f.ret(&b, body, s)
	fmt.Fprintf(w, "func %s%s(%s) %s {\n%s}\n\n", name, tps, strings.Join(params, ", "), GoType(ft.Result), b.String())
}

// test emits the n-th test of its module: a function returning its Bool, or for an effect test
// its Task Bool.
//
//	func test__Todo__1() bool {
//		return rtesting.Eq(Todo__countOpen(…), int64(1))
//	}
func (g *gen) test(w *strings.Builder, t *ir.Test, n int) {
	if p, ok := t.Body.(*ir.TestProp); ok {
		g.propTest(w, t, p, n)
		return
	}
	f := &fn{g: g}
	var b strings.Builder
	result := "bool"
	if t.Effect {
		result = "eff.Task[bool]"
	}
	if t.Effect {
		f.retK(&b, t.Body, newScope(), f.task)
	} else {
		f.ret(&b, t.Body, newScope())
	}
	fmt.Fprintf(w, "// %s is test %s of module %s.\nfunc %s() %s {\n%s}\n\n", testFunc(t.Module, n), strconv.Quote(t.Name), t.Module,
		testFunc(t.Module, n), result, b.String())
}

// checkDecl emits brand b's `where` check: its function applied to the value.
//
//	func check__M__Slug(v string) bool {
//		return std.TextMatches("^[a-z]+$", v)
//	}
func (g *gen) checkDecl(w *strings.Builder, b *ir.Brand) {
	f := &fn{g: g}
	s := newScope()
	v := s.declare("v")
	key := "v"
	arg := &ir.Var{Typed: ir.Typed{Ty: b.Base}, Kind: ir.VarLocal, Name: key}
	var body ir.Expr
	if pa, ok := b.Check.(*ir.Partial); ok && pa.Missing == 1 {
		body = &ir.Call{Typed: ir.Typed{Ty: types.Bool}, Fn: pa.Fn, Args: append(slices.Clone(pa.Given), arg)}
	} else if l, ok := b.Check.(*ir.Lambda); ok && len(l.Params) == 1 {
		body = &ir.Let{Typed: ir.Typed{Ty: types.Bool}, Name: l.Params[0].Name, T: b.Base, Value: arg, Body: l.Body}
	} else {
		body = &ir.Call{Typed: ir.Typed{Ty: types.Bool}, Fn: b.Check, Args: []ir.Expr{arg}}
	}
	var out strings.Builder
	f.ret(&out, body, s)
	fmt.Fprintf(w, "// %s is the `where` check of brand %s.%s.\nfunc %s(%s %s) bool {\n%s}\n\n",
		checkName(b.Module, b.Name), b.Module, b.Name, checkName(b.Module, b.Name), v, GoType(b.Base), out.String())
}

// widenFunc emits the function that widens `requires` page pg's Session to App's: the required
// field becomes Just of its value, the others are copied.
//
//	func widen__Home__Session(s Home__Session) App__Session {
//		return App__Session{User: rt.Just(s.User), N: s.N}
//	}
func widenFunc(w *strings.Builder, pg *ir.Page, app *ir.RecordType, boxed boxedSet) {
	var fs []string
	for _, f := range app.Fields {
		v := "s." + Field(f.Name) // a page's narrowed Session never reaches itself: no field is boxed
		if slices.Contains(pg.Requires, f.Name) || f.Name == pg.Silo {
			v = "rt.Just(" + v + ")"
		}
		if boxed.has(app.Module, app.Name, f.Name) {
			v = "new(" + v + ")"
		}
		fs = append(fs, Field(f.Name)+": "+v)
	}
	fmt.Fprintf(w, "func %s(s %s) %s {\nreturn %s{%s}\n}\n\n", widenName(pg.Module), GoName(pg.Module, "Session"),
		GoName(app.Module, app.Name), GoName(app.Module, app.Name), strings.Join(fs, ", "))
}
